from typing import Final
from openassembler.pyfront import *
COEFFICIENTS:Final=(3, -5, 7)
@device
def helper(x:i64)->i64:
    value=i64(0)
    for c in COEFFICIENTS:
        value=value*x+i64(c)
    return value
@kernel
def k(a:Array(i64),out:Array(i64)):
    out[0]=helper(a[0])

